91 static int bp_icache_retention_probe(u64 *status)
92 {
93 	unsigned long err = 0, value = 0;
94 
95 	asm volatile("1: csrr %[value], 0x5c1\n"
96 		     "2:\n"
97 		     _ASM_EXTABLE_UACCESS_ERR_ZERO(1b, 2b, %[err], %[value])
98 		     : [err] "+&r" (err), [value] "+&r" (value)
99 		     : : "memory");
100 	if (err || !(value & (1UL << 63)))
101 		return -ENODEV;
102 	*status = value;
103 	return 0;
104 }
